<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Khóa học của tôi | HànNgữ</title><link rel="stylesheet" href="style.css"><style>.page{max-width:1000px;margin:auto;padding:110px 24px}.card{background:#fff;padding:22px;border-radius:16px;box-shadow:0 6px 25px #0f172a12;margin:14px 0}.paid{color:#047857;font-weight:800}</style></head><body><?php include 'sidebar.php'; ?><main class="page"><h1>Khóa học của tôi</h1><div id="list">Đang tải...</div></main><script>fetch('api.php?action=get_my_orders').then(r=>r.json()).then(r=>{let el=document.getElementById('list');if(!r.success){el.innerHTML='<p>Vui lòng <a href="login.php">đăng nhập</a>.</p>';return}el.innerHTML=r.orders.length?r.orders.map(o=>`<article class="card"><span class="paid">Đã đăng ký</span><h2>${o.course_title}</h2><p>Mã đơn: <b>${o.order_code}</b> · Miễn phí</p>${o.status==='paid'?`<a class="btn btn--primary" href="learn_course.php?slug=${o.course_slug}">Vào học</a>`:`<a class="btn btn--outline" href="course.php?slug=${o.course_slug}">Xem khóa học</a>`}</article>`).join(''):'<p>Bạn chưa đăng ký khóa học nào.</p>'});</script></body></html>
